Find all real values of $x$ that satisfy $\frac{1}{x(x+1)}-\frac1{(x+1)(x+2)} < \frac13.$ (Give your answer in interval notation.)

Put your final answer within \boxed{}.

#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x;
    double lower_bound = 0;
    double upper_bound = 1;

    while (true) {
        x = (lower_bound + upper_bound) / 2;
        double left_side = 1 / (x * (x + 1)) - 1 / ((x + 1) * (x + 2));
        double right_side = 1 / 3;

        if (left_side < right_side) {
            upper_bound = x;
        } else {
            lower_bound = x;
        }

        if (abs(left_side - right_side) < 1e-9) {
            break;
        }
    }

    cout << "The solution is x = " << x << endl;

    return 0;
}

